import {canReports} from './workshop-model.js';
import {categoryOrder,sortProducts} from './product-order.js';
import {buildStock,summarizeSales,reportPeriod,peruDay,dayOffset,csv} from './report-model.js';
import {storeLabel} from './session.js';
export function createAdminReports({db,state,guard,ready,render,notice,esc,money,date}){
 const reportViews=['stock_general','reporte_ventas'];const today=()=>peruDay(Date.now());
 let generation=0,stock=null,sales=null,stockError='',salesError='',stockBusy=false,salesBusy=false,stockPage=0,salePage=0;
 let stockFilters={search:'',category:'',status:'',store:'',active:'active'},filters={from:today(),to:today(),store:''},draft={...filters};
 const active=()=>canReports(state().me?.role)&&!!state().user&&ready();
 const refreshView=()=>{if(active()&&reportViews.includes(state().view))render();};
 const quantityFormat=new Intl.NumberFormat('es-PE',{maximumFractionDigits:3});
 const qty=n=>n===null?'Sin registro':quantityFormat.format(n);
 const amount=n=>money(n/100),shortDay=d=>d.slice(8)+'/'+d.slice(5,7),normal=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 async function authorize(){if(!active())throw Error('Consulta disponible para administración y gerencia.');const owner=state().user.id,g=generation;await guard();const r=await db.rpc('charito_security_status');if(r.error)throw Error('No se pudo verificar el acceso al reporte. Comprueba tu conexión y vuelve a intentarlo.');if(!r.data?.session_valid||!r.data?.ready||r.data?.role!==state().me?.role||!(r.data?.role==='admin'&&r.data?.can_manage_users===true||r.data?.role==='owner'&&r.data?.can_view_reports===true))throw Error('Inicia sesión con un perfil autorizado para consultar reportes.');if(!active()||state().user.id!==owner||g!==generation)throw Error('La sesión cambió.');return {owner,g};}
 const current=token=>token.g===generation&&active()&&state().user.id===token.owner;
 async function read(query){const r=await query;if(r.error)throw Error('No se pudo consultar el reporte: '+r.error.message);return r.data||[];}
 async function paged(make){const all=[];for(let n=0;n<100000;n+=800){const page=await read(make().range(n,n+799));all.push(...page);if(page.length<800)return all;}throw Error('Hay demasiados registros. Selecciona un periodo más corto. No se muestran resultados parciales.');}
 async function catalog(){const [stores,products]=await Promise.all([read(db.from('charito_stores').select('id,name,active').order('name')),paged(()=>db.from('charito_products').select('id,sku,name,category,unit,quantity_step,price,active').order('sku').order('id'))]);stores.forEach(s=>s.name=storeLabel(s.name));return {stores,products};}
 async function loadStock(force=false){
  if(!active()||stockBusy||!force&&stock&&Date.now()-stock.loaded<60000)return;
  stockBusy=true;stockError='';const g=generation;refreshView();
  try{const token=await authorize(),c=await catalog();
   const shifts=(await Promise.all(c.stores.map(s=>read(db.from('charito_shifts').select('id,store_id,label,status,sales_mode,opened_at,closed_at').eq('store_id',s.id).order('status',{ascending:false}).order('opened_at',{ascending:false}).limit(1))))).flat();
   const ids=shifts.map(s=>s.id),open=shifts.filter(s=>s.status==='open').map(s=>s.id);
   const [counts,movements,transfers]=await Promise.all([
    ids.length?paged(()=>db.from('charito_counts').select('shift_id,product_id,opening_qty,closing_qty').in('shift_id',ids).order('shift_id').order('product_id')):[],
    open.length?paged(()=>db.from('charito_stock_movements').select('id,shift_id,product_id,quantity').in('shift_id',open).order('id')):[],
    paged(()=>db.from('charito_transfers').select('id,status,destination_store_id,charito_transfer_lines(product_id,quantity)').eq('status','in_transit').order('id'))
   ]);
   // If a shift closed/replaced while reading, do not publish a mixed stock snapshot.
   const verify=(await Promise.all(c.stores.map(s=>read(db.from('charito_shifts').select('id,status').eq('store_id',s.id).order('status',{ascending:false}).order('opened_at',{ascending:false}).limit(1))))).flat();
   if(verify.some(s=>!shifts.some(old=>old.id===s.id&&old.status===s.status))||verify.length!==shifts.length)throw Error('Un turno cambió durante la consulta. Pulsa Actualizar stock para cargar su nuevo saldo.');
   if(current(token)){stock={...c,...buildStock({...c,shifts,counts,movements,transfers}),loaded:Date.now()};stockPage=0;}
  }catch(e){if(g===generation&&active())stockError=e.message;}finally{if(g===generation){stockBusy=false;refreshView();}}
 }
 async function loadSales(force=false){
  if(!active()||salesBusy||!force&&sales&&JSON.stringify(sales.filters)===JSON.stringify(filters)&&Date.now()-sales.loaded<60000)return;
  let period;try{period=reportPeriod(filters.from,filters.to);}catch(e){notice(e.message,true);return;}
  salesBusy=true;salesError='';const g=generation,selected={...filters};refreshView();
  try{const token=await authorize(),c=await catalog();
   const makeSales=()=>{let q=db.from('charito_sales').select('id,store_id,shift_id,total,discount,status,created_at,charito_sale_lines(product_id,quantity,unit_price),charito_cash_entries(kind,method,amount)').gte('created_at',period.start).lt('created_at',period.end);if(selected.store)q=q.eq('store_id',selected.store);return q.order('created_at',{ascending:false}).order('id');};
   const makeLegacy=()=>{let q=db.from('charito_shifts').select('id,store_id,label,closed_at,charito_closures(inventory_sales)').eq('sales_mode','count').eq('status','closed').gte('closed_at',period.start).lt('closed_at',period.end);if(selected.store)q=q.eq('store_id',selected.store);return q.order('closed_at',{ascending:false}).order('id');};
   const [rows,legacy]=await Promise.all([paged(makeSales),paged(makeLegacy)]);
   if(current(token)){sales={...c,rows,legacy,period,filters:selected,summary:summarizeSales({sales:rows,legacy,...c,period}),loaded:Date.now()};salePage=0;}
  }catch(e){if(g===generation&&active())salesError=e.message;}finally{if(g===generation){salesBusy=false;refreshView();}}
 }
 const options=(items,value,blank)=>`<option value="">${blank}</option>`+items.map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('');
 const metric=(title,value,note='',primary=false)=>`<div class="report-metric ${primary?'report-primary':''}"><span>${title}</span><strong>${value}</strong>${note?`<small>${note}</small>`:''}</div>`;
 const message=(error,busy,loaded)=>`${error?`<div class="report-alert" role="alert">${esc(error)}${loaded?' Se conserva la consulta anterior, que puede estar desactualizada.':''}</div>`:''}${busy?'<p class="report-loading" role="status">Consultando registros de las tiendas…</p>':''}`;
 const table=(heads,rows)=>`<div class="report-table-wrap"><table class="report-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map((c,i)=>`<td data-label="${esc(heads[i].replace(/<[^>]*>/g,''))}">${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${heads.length}" class="report-empty">No hay registros con estos filtros.</td></tr>`}</tbody></table></div>`;
 const pager=(page,total,size,kind)=>`<div class="report-pager"><span>${total?`${page*size+1}–${Math.min((page+1)*size,total)} de ${total}`:'0 resultados'}</span><button type="button" class="secondary" data-report-page="${kind}" data-delta="-1" ${page===0?'disabled':''}>Anterior</button><button type="button" class="secondary" data-report-page="${kind}" data-delta="1" ${(page+1)*size>=total?'disabled':''}>Siguiente</button></div>`;
 function filteredStock(){if(!stock)return [];return sortProducts(stock.rows,stock.products,{product:r=>r.product}).filter(r=>{
  const p=r.product,locations=r.stores.filter(s=>!stockFilters.store||s.store.id===stockFilters.store);
  if(stockFilters.active==='active'&&!p.active||stockFilters.active==='inactive'&&p.active||stockFilters.category&&p.category!==stockFilters.category)return false;
  if(stockFilters.search&&!normal(p.name+' '+p.category+' '+p.sku).includes(normal(stockFilters.search.trim())))return false;
  return !stockFilters.status||locations.some(s=>stockFilters.status==='unknown'?s.qty===null:stockFilters.status==='negative'?s.qty!==null&&s.qty<0:stockFilters.status==='zero'?s.qty===0:stockFilters.status==='available'?s.qty!==null&&s.qty>0:s.incoming>0);
 });}
 function stockView(){if(!active())return '<div class="warn">Consulta exclusiva del administrador.</div>';
  const stores=stock?.stores||state().data.stores||[],rows=filteredStock(),locations=stores.filter(s=>!stockFilters.store||s.id===stockFilters.store);
  const header=`<div class="report-heading"><div><span class="report-eyebrow">ADMINISTRACIÓN · AMBAS TIENDAS</span><h2>Stock por tienda</h2></div><button type="button" data-report-refresh="stock" ${stockBusy?'disabled':''}>Actualizar stock</button></div>`;
  const filter=`<div class="report-filters report-no-print"><label class="report-search">Buscar producto<input data-stock-filter="search" type="search" value="${esc(stockFilters.search)}" placeholder="Nombre, categoría o código"></label><label>Tienda<select data-stock-filter="store">${options(stores.map(s=>[s.id,s.name]),stockFilters.store,'Todas las tiendas')}</select></label><label>Categoría<select data-stock-filter="category">${options(categoryOrder(stock?.products||[]).map(c=>[c,c]),stockFilters.category,'Todas')}</select></label><label>Stock<select data-stock-filter="status">${options([['available','Con stock'],['zero','Agotado'],['unknown','Sin registro'],['negative','Saldo negativo'],['incoming','Por recibir']],stockFilters.status,'Todos los saldos')}</select></label><label>Productos<select data-stock-filter="active">${[['active','Activos'],['inactive','Inactivos'],['all','Todos']].map(([k,v])=>`<option value="${k}" ${k===stockFilters.active?'selected':''}>${v}</option>`).join('')}</select></label></div>`;
  const cards=stores.map(s=>{const shift=stock?.latest.get(s.id);return `<div class="report-store"><strong>${esc(s.name)}</strong><span class="report-tag">${!stock?'Consultando…':shift?.status==='open'?'Turno abierto':shift?'Último cierre':'Sin registros'}</span><small>${shift?`${esc(shift.label)} · ${date(shift.status==='open'?shift.opened_at:shift.closed_at)}`:stock?'Aún no se ha registrado un conteo.':'Buscando el último saldo de esta tienda…'}</small></div>`;}).join('');
  const metrics=stock?`<div class="report-metrics">${metric('Productos del catálogo',stock.rows.length,'',true)}${metric('Productos agotados',stock.rows.filter(r=>r.stores.some(s=>s.qty===0)).length,'')}${metric('Sin saldo registrado',stock.rows.filter(r=>r.stores.some(s=>s.qty===null)).length,'')}</div>`:'';
  const rowsHtml=stock?stockResults(rows,locations):'';
  return `<section class="admin-report" data-admin-report="stock">${header}${message(stockError,stockBusy,stock)}<div class="report-stores">${cards}</div>${filter}${metrics}<div data-stock-results>${rowsHtml}</div></section>`;
 }
 function stockResults(rows=filteredStock(),locations=(stock?.stores||[]).filter(s=>!stockFilters.store||s.id===stockFilters.store)){
  stockPage=Math.min(stockPage,Math.max(0,Math.ceil(rows.length/40)-1));
  return `<div class="report-panel"><div class="report-panel-head"><h3>Saldos por producto</h3><button type="button" class="secondary report-no-print" data-report-export="stock">Descargar CSV</button></div>${table(['Producto','Unidad',...locations.map(s=>esc(s.name)),...(locations.length>1?['Total registrado']:[])],rows.slice(stockPage*40,(stockPage+1)*40).map(r=>{const loc=r.stores.filter(s=>locations.some(l=>l.id===s.store.id)),known=loc.every(s=>s.qty!==null);return [`<strong>${esc(r.product.name)}</strong><small>${esc(r.product.category)} · ${esc(r.product.sku)}${r.product.active?'':' · Inactivo'}</small>`,esc(r.product.unit),...loc.map(s=>`<strong class="${s.qty===0?'report-zero':s.qty<0?'report-negative':''}">${qty(s.qty)}</strong><small>${esc(s.basis)}${s.incoming?` · Por recibir: ${qty(s.incoming)}`:''}</small>`),...(locations.length>1?[`<strong>${known?qty(loc.reduce((a,s)=>a+s.qty,0)):'—'}</strong>${!known?'<small>Faltan registros</small>':''}`]:[])];}))}${pager(stockPage,rows.length,40,'stock')}</div><p class="report-timestamp">Consulta: ${date(stock.loaded)}</p>`;
 }
 function salesView(){if(!active())return '<div class="warn">Consulta exclusiva del administrador.</div>';
  const stores=sales?.stores||state().data.stores||[];
  return `<section class="admin-report" data-admin-report="sales"><div class="report-heading"><div><span class="report-eyebrow">ADMINISTRACIÓN · VENTAS</span><h2>Ventas del periodo</h2></div><button type="button" data-report-refresh="sales" ${salesBusy?'disabled':''}>Actualizar reporte</button></div>${message(salesError,salesBusy,sales)}<div class="report-filters report-no-print"><label>Desde<input type="date" data-sales-filter="from" value="${esc(draft.from)}" required></label><label>Hasta<input type="date" data-sales-filter="to" value="${esc(draft.to)}" required></label><label>Tienda<select data-sales-filter="store">${options(stores.map(s=>[s.id,s.name]),draft.store,'Todas las tiendas')}</select></label><button type="button" data-report-apply ${salesBusy?'disabled':''}>Consultar</button><div class="report-presets">${[['today','Hoy'],['week','Últimos 7 días'],['month','Este mes']].map(([k,l])=>`<button type="button" class="secondary" data-report-preset="${k}" ${salesBusy?'disabled':''}>${l}</button>`).join('')}</div></div>${sales?salesContent():!salesBusy?'<div class="report-empty">Pulsa Consultar para obtener el reporte.</div>':''}</section>`;
 }
 function salesContent(){const r=sales.summary,storeName=id=>sales.stores.find(s=>s.id===id)?.name||'Tienda',scope=sales.filters.store?storeName(sales.filters.store):'Todas las tiendas';
  return `<div id="admin-report-print"><div class="report-period"><div><strong>Pastelería Charito’s</strong><span>${esc(scope)} · ${sales.period.from} al ${sales.period.to} · Hora de Perú</span></div><div class="report-actions report-no-print"><button type="button" class="secondary" data-report-export="sales">Descargar CSV</button><button type="button" class="secondary" data-report-print>Imprimir resumen / PDF</button></div></div><div class="report-metrics">${metric('Ventas del periodo',amount(r.total),'Ventas directas vigentes + cierres por conteo.',true)}${metric('Efectivo · ventas directas',amount(r.cash),'')}${metric('Yape · ventas directas',amount(r.yape),'')}${metric('Ticket promedio',r.average===null?'—':amount(r.average),`${r.tickets} ventas directas vigentes.`)}</div>${r.mismatch?`<div class="report-alert">${r.mismatch} ventas tienen pagos que no coinciden con su total. Revisa sus registros antes de conciliar.</div>`:''}<div class="report-inline-stats"><span>Descuentos en ventas directas <strong>${amount(r.discount)}</strong></span><span>Anuladas (excluidas) <strong>${r.voided} · ${amount(r.voidedAmount)}</strong></span><span>Ventas por conteo <strong>${amount(r.legacyTotal)}</strong></span></div><div class="report-panel"><h3>Ventas por día</h3>${dailyChart(r.days)}</div><div class="report-two"><div class="report-panel"><h3>Comparación por tienda</h3>${table(['Tienda','Venta directa','Por conteo','Total'],r.byStore.filter(s=>!sales.filters.store||s.store.id===sales.filters.store).map(s=>[esc(s.store.name),amount(s.net),amount(s.legacy),`<strong>${amount(s.net+s.legacy)}</strong>`]))}</div><div class="report-panel"><h3>Productos más vendidos</h3><p class="small muted">Ventas directas vigentes · importe antes de descuentos.</p>${table(['Producto','Cantidad','Importe'],r.top.slice(0,10).map(p=>[`<strong>${esc(p.product.name)}</strong><small>${esc(p.product.category)}</small>`,`${qty(p.qty)} ${esc(p.product.unit)}`,amount(p.gross)]))}</div></div><div class="report-panel report-no-print"><div class="report-panel-head"><h3>Detalle de ventas directas</h3><span class="report-tag">${sales.rows.length} registros</span></div>${table(['Venta / fecha','Tienda','Estado','Efectivo','Yape','Descuento','Venta neta'],sales.rows.slice(salePage*25,(salePage+1)*25).map(s=>{const pay=method=>(s.charito_cash_entries||[]).filter(e=>e.kind==='sale_payment'&&e.method===method).reduce((a,e)=>a+Math.round(Number(e.amount)*100),0);return [`<strong>${esc(s.id.slice(0,8))}</strong><small>${date(s.created_at)}</small>`,esc(storeName(s.store_id)),`<span class="report-tag ${s.status==='voided'?'report-cancelled':''}">${s.status==='voided'?'Anulada':'Vigente'}</span>`,s.status==='voided'?'—':amount(pay('cash')),s.status==='voided'?'—':amount(pay('yape')),amount(Math.round(Number(s.discount)*100)),s.status==='voided'?`<s>${money(s.total)}</s>`:`<strong>${money(s.total)}</strong>`];}))}${pager(salePage,sales.rows.length,25,'sales')}</div>${sales.legacy.length?`<div class="report-panel"><h3>Cierres con ventas por conteo</h3><p class="report-scope">Fecha de cierre · excluidos de efectivo, Yape y ticket promedio.</p>${table(['Cierre','Tienda','Turno','Venta por conteo'],sales.legacy.slice(0,50).map(s=>{const c=Array.isArray(s.charito_closures)?s.charito_closures[0]:s.charito_closures;return [date(s.closed_at),esc(storeName(s.store_id)),esc(s.label),c?money(c.inventory_sales):'Sin cierre registrado'];}))}${sales.legacy.length>50?'<p>Se muestran 50 cierres. El CSV incluye todos los cierres consultados.</p>':''}</div>`:''}<p class="report-scope">Ventas de productos · excluye pedidos, egresos y retiros.</p><p class="report-timestamp">Actualizado: ${date(sales.loaded)} · ${sales.period.from} al ${sales.period.to} · ${esc(scope)}</p></div>`;
 }
 function dailyChart(days){
  // Group longer periods into consecutive weeks to keep the chart legible on phones.
  const size=days.length>45?7:1,buckets=[];for(let i=0;i<days.length;i+=size){const part=days.slice(i,i+size);buckets.push({label:shortDay(part[0].day)+(part.length>1?'–'+shortDay(part.at(-1).day):''),total:part.reduce((n,d)=>n+d.total,0)});}
  const max=Math.max(1,...buckets.map(b=>Math.abs(b.total)));
  return `<div class="report-chart" role="list" aria-label="Ventas por ${size===1?'día':'semana'}">${buckets.map(b=>`<div class="report-bar-row" role="listitem"><span>${b.label}</span><div class="report-bar-track"><i style="width:${Math.max(b.total===0?0:1,Math.abs(b.total)/max*100)}%" class="${b.total<0?'report-bar-negative':''}"></i></div><strong>${amount(b.total)}</strong></div>`).join('')}</div>`;
 }
 function download(kind){let rows,name;
  if(kind==='stock'&&stock){const locations=stock.stores.filter(s=>!stockFilters.store||s.id===stockFilters.store);rows=[['Charito - Stock registrado',date(stock.loaded)],['Código','Producto','Categoría','Unidad','Activo',...locations.flatMap(s=>[s.name,'Base del saldo','Por recibir','Fecha del turno / cierre'])],...filteredStock().map(r=>[r.product.sku,r.product.name,r.product.category,r.product.unit,r.product.active?'Sí':'No',...r.stores.filter(s=>locations.some(l=>l.id===s.store.id)).flatMap(s=>[s.qty===null?'Sin registro':s.qty,s.basis,s.incoming,s.shift?date(s.shift.closed_at||s.shift.opened_at):'Sin turno'])])];name='stock-'+today();}
  else if(kind==='sales'&&sales){const r=sales.summary;rows=[['Charito - Reporte de ventas',sales.filters.from,sales.filters.to,'Hora de Perú'],['Tienda',sales.stores.find(s=>s.id===sales.filters.store)?.name||'Todas las tiendas'],['Actualizado',date(sales.loaded)],['Ventas totales',(r.total/100).toFixed(2)],['Ventas directas',(r.net/100).toFixed(2)],['Ventas por conteo',(r.legacyTotal/100).toFixed(2)],['Efectivo directo',(r.cash/100).toFixed(2)],['Yape directo',(r.yape/100).toFixed(2)],['Descuentos directos',(r.discount/100).toFixed(2)],[],['Tienda','Venta directa','Venta por conteo','Total'],...r.byStore.filter(t=>!sales.filters.store||t.store.id===sales.filters.store).map(t=>[t.store.name,(t.net/100).toFixed(2),(t.legacy/100).toFixed(2),((t.net+t.legacy)/100).toFixed(2)]),[],['Producto','Categoría','Cantidad vendida','Unidad','Importe antes de descuentos'],...r.top.map(t=>[t.product.name,t.product.category,t.qty,t.product.unit,(t.gross/100).toFixed(2)]),[],['ID','Fecha Perú','Tienda','Estado','Total registrado','Descuento','Venta neta incluida','Efectivo incluido','Yape incluido'],...sales.rows.map(s=>[s.id,date(s.created_at),sales.stores.find(t=>t.id===s.store_id)?.name,s.status==='voided'?'Anulada':'Vigente',s.total,s.discount,s.status==='completed'?s.total:0,...['cash','yape'].map(method=>s.status==='completed'?((s.charito_cash_entries||[]).filter(e=>e.kind==='sale_payment'&&e.method===method).reduce((n,e)=>n+Math.round(Number(e.amount)*100),0)/100).toFixed(2):'0.00')]),[],['Cierre por conteo','Fecha Perú','Tienda','Turno','Venta'],...sales.legacy.map(s=>{const c=Array.isArray(s.charito_closures)?s.charito_closures[0]:s.charito_closures;return [s.id,date(s.closed_at),sales.stores.find(t=>t.id===s.store_id)?.name,s.label,c?.inventory_sales??'Sin cierre'];})];name='ventas-'+sales.filters.from+'-'+sales.filters.to;}
  else return;if(window.AndroidHost?.saveDocument){const error=window.AndroidHost.saveDocument(csv(rows),'charito-'+name+'.csv','text/csv');if(typeof error==='string'&&error)throw Error(error);return;}const url=URL.createObjectURL(new Blob([csv(rows)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='charito-'+name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
 async function click(b){if(!b.matches('[data-report-refresh],[data-report-apply],[data-report-preset],[data-report-export],[data-report-page],[data-report-print]'))return false;if(!active())throw Error('Consulta disponible para administración y gerencia.');
  if(b.dataset.reportRefresh){if(b.dataset.reportRefresh==='stock')await loadStock(true);else await loadSales(true);}
  else if(b.hasAttribute('data-report-apply')||b.dataset.reportPreset){if(salesBusy)return true;const p=b.dataset.reportPreset;if(p){draft.to=today();draft.from=p==='week'?dayOffset(draft.to,-6):p==='month'?draft.to.slice(0,8)+'01':draft.to;}reportPeriod(draft.from,draft.to);filters={...draft};await loadSales(true);}
  else if(b.dataset.reportPage){if(b.dataset.reportPage==='stock')stockPage+=Number(b.dataset.delta);else salePage+=Number(b.dataset.delta);refreshView();}
  else if(b.dataset.reportExport){await authorize();download(b.dataset.reportExport);}
  else if(b.hasAttribute('data-report-print')){await authorize();document.body.classList.add('printing-admin-report');try{window.print();}finally{document.body.classList.remove('printing-admin-report');}}
  return true;
 }
 function input(e){if(!active())return;const el=e.target;if(el.dataset.salesFilter){draft[el.dataset.salesFilter]=el.value;return;}if(!el.dataset.stockFilter)return;stockFilters[el.dataset.stockFilter]=el.value;stockPage=0;if(el.dataset.stockFilter==='search'){
   const output=document.querySelector('[data-stock-results]');if(output&&stock)output.innerHTML=stockResults();
  }else refreshView();}
 function enter(view){if(view==='stock_general')void loadStock();else if(view==='reporte_ventas')void loadSales();}
 function clear(){generation++;stock=null;sales=null;stockBusy=false;salesBusy=false;stockError='';salesError='';stockPage=0;salePage=0;stockFilters={search:'',category:'',status:'',store:'',active:'active'};filters={from:today(),to:today(),store:''};draft={...filters};}
 return {stockView,salesView,click,input,enter,clear,refresh:()=>state().view==='stock_general'?loadStock(true):state().view==='reporte_ventas'?loadSales(true):Promise.resolve()};
}
